def minPath(grid, k):
    n = len(grid)

    # Priority queue stores (path_list, current_row, current_col)
    # path_list is a list of values, which is used for lexicographical comparison
    pq = []

    # Initialize PQ with all possible starting points
    for r in range(n):
        for c in range(n):
            start_val = grid[r][c]
            # Heap stores (path_list, r, c). Python's heapq compares lists lexicographically.
            heapq.heappush(pq, ([start_val], r, c))

    while pq:
        path, r, c = heapq.heappop(pq)

        if len(path) == k:
            # Since we use a min-heap ordered by path_list, the first path of length k found is the lexicographically smallest.
            return path

        # Explore neighbors
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc

            # Check bounds
            if 0 <= nr < n and 0 <= nc < n:
                next_val = grid[nr][nc]
                new_path = path + [next_val]
                heapq.heappush(pq, (new_path, nr, nc))

    # Should not be reached given problem constraints (k >= 1 and grid is connected)
